code.content:
span.tag {
  display: inline-block;   /* now padding, width and vertical margin work */
  padding: 4px 8px;
  margin-block: 4px;
}

nav a {
  display: block;          /* full-width clickable area */
  padding: 12px 16px;
}

*, *::before, *::after {
  box-sizing: border-box;
}

.card {
  width: 300px;
  padding: 20px;
  border: 1px solid #ddd;
  margin: 16px;
}
/* content-box: 300 + 40 + 2 = 342px wide
   border-box:  300px wide (content area is 258px) */

.navbar {
  display: flex;
  align-items: center;
  gap: 1rem;
}
.navbar .spacer { flex: 1; }          /* pushes the rest to the right */

.card-row {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}
.card-row > .card {
  flex: 1 1 280px;                    /* grow, shrink, start at 280px */
  min-width: 0;
}

.center {
  display: flex;
  justify-content: center;
  align-items: center;
}

.layout {
  display: grid;
  grid-template-columns: 16rem 1fr;
  grid-template-areas:
    "sidebar header"
    "sidebar main";
  min-height: 100vh;
}
.sidebar { grid-area: sidebar; }
.header  { grid-area: header; }
.main    { grid-area: main; }

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
  gap: 1rem;
}

@media (max-width: 768px) {
  .layout {
    grid-template-columns: 1fr;
    grid-template-areas: "header" "main";
  }
  .sidebar { display: none; }
}

.card { position: relative; }

.card .badge {
  position: absolute;      /* relative to .card */
  top: 8px;
  right: 8px;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
}

.toast {
  position: fixed;
  bottom: 1rem;
  right: 1rem;
}

.overlay {
  position: fixed;
  inset: 0;                /* top, right, bottom, left = 0 */
}

/* Base: mobile */
.container { width: min(100% - 2rem, 72rem); margin-inline: auto; }
.grid { display: grid; gap: 1rem; grid-template-columns: 1fr; }
.sidebar { display: none; }
h1 { font-size: clamp(1.5rem, 1.2rem + 1.5vw, 2.25rem); }
img { max-width: 100%; height: auto; }

/* Tablet and up */
@media (min-width: 768px) {
  .grid { grid-template-columns: repeat(2, 1fr); }
}

/* Desktop and up */
@media (min-width: 1024px) {
  .grid { grid-template-columns: repeat(3, 1fr); }
  .sidebar { display: block; }
}

html { font-size: 100%; }             /* 16px unless the user changed it */

body { font-size: 1rem; line-height: 1.5; }
h1   { font-size: 2rem; }             /* 32px */

.button {
  font-size: 0.875rem;
  padding: 0.5em 1em;                 /* scales with the button's own font size */
}

.hero  { min-height: 100dvh; }
.prose { max-width: 65ch; }

a:hover, a:focus-visible { text-decoration: underline; }

tr:nth-child(even) { background: #f6f7f9; }
li:not(:last-child) { border-bottom: 1px solid #e3e6ec; }

input:invalid:not(:placeholder-shown) { border-color: #c42c2c; }
.field:focus-within label { color: #2b59e0; }
.card:has(img) { padding-top: 0; }

.required::after {
  content: " *";
  color: #c42c2c;
}
::selection { background: #ffe14d; }

/* Grid: shortest */
.parent { display: grid; place-items: center; min-height: 100dvh; }

/* Flexbox */
.parent { display: flex; justify-content: center; align-items: center; }

/* Horizontal only */
.container { max-width: 60rem; margin-inline: auto; }

/* Absolute overlay */
.modal {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.is-removed   { display: none; }
.is-invisible { visibility: hidden; }

.fade {
  opacity: 0;
  visibility: hidden;
  transition: opacity 150ms ease, visibility 150ms;
}
.fade.is-open { opacity: 1; visibility: visible; }

/* Visible to screen readers only */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.button {
  transition: background-color 150ms ease, transform 150ms ease;
}
.button:hover  { background-color: #2b59e0; }
.button:active { transform: translateY(1px); }

@keyframes spin {
  to { transform: rotate(360deg); }
}
.spinner { animation: spin 800ms linear infinite; }

@keyframes rise {
  from { opacity: 0; transform: translateY(8px); }
}
.toast { animation: rise 160ms ease-out; }

@media (prefers-reduced-motion: reduce) {
  .spinner, .toast, .button { animation: none; transition: none; }
}
